from pathlib import Path
import base64, shutil, tempfile
root=Path.cwd()
page=root/'app/page.tsx'
css=root/'app/globals.css'
if not page.is_file() or not css.is_file():
    raise SystemExit('Execute no terminal da pasta /workspaces/planilha-manel.')
old=base64.b64decode('').decode()
new=base64.b64decode('').decode()
style=base64.b64decode('').decode()
text=page.read_text()
styles=css.read_text()
if new in text and "[selectedHouse,setSelectedHouse]=useState('')" in text and style in styles:
    print('Ranking de contas ja aplicado. Proximo comando: pnpm build')
    raise SystemExit(0)
if text.count(old)!=1 or text.count("[selectedAccount,setSelectedAccount]=useState('')")!=1:
    raise SystemExit('A tela de contas mudou. Envie app/page.tsx para adaptar sem perder alteracoes.')
updated=text.replace(old,new,1).replace("[selectedAccount,setSelectedAccount]=useState('')","[selectedHouse,setSelectedHouse]=useState('')",1)
backup=Path(tempfile.mkdtemp(prefix='planilha-contas-backup-'))
shutil.copy2(page,backup/'page.tsx')
shutil.copy2(css,backup/'globals.css')
page.write_text(updated)
if style not in styles:
    css.write_text(styles+style)
print('Atualizacao aplicada: contas do maior saldo disponivel para o menor, com filtros por casa e pessoa.')
print('Backup: '+str(backup))
print('Proximo comando: pnpm build')
